// manifest.json
const manifest = JSON.stringify({name:'JiduOS 电竞优化系统',short_name:'JiduOS',description:'Windows电竞级系统精调，远程一对一',start_url:'/',display:'standalone',background_color:'#030609',theme_color:'#00ccff',icons:[{src:'/jiduLOGO-400.png',sizes:'192x192',type:'image/png'},{src:'/jiduLOGO-400.png',sizes:'512x512',type:'image/png',purpose:'any maskable'}]});
fs.writeFileSync(outDir + '/manifest.json', manifest);
console.log('manifest updated');

// Push to Baidu
const http = require('http');
const baiduCfg = JSON.parse(fs.readFileSync(__dirname+'/baidu-config.json','utf8'));
const baiduBody = baiduCfg.urls.join('\n');
const baiduApi = http.request({hostname:'data.zz.baidu.com',port:80,path:'/urls?site='+baiduCfg.site+'&token='+baiduCfg.token,method:'POST',headers:{'Content-Type':'text/plain','Content-Length':Buffer.byteLength(baiduBody)}},res=>{let d='';res.on('data',c=>d+=c);res.on('end',()=>{try{const r=JSON.parse(d);console.log(r.error ? 'Baidu err: '+r.message : 'Baidu ok: '+r.success+' pushed, '+r.remain+' remain')}catch(e){console.log('Baidu push: '+d)}})});
baiduApi.on('error',e=>console.log('Baidu push err: '+e.message));
baiduApi.write(baiduBody);
baiduApi.end();

// Also update project copy
fs.writeFileSync('d:/AI/jidu-apbx-system-v2/JiduOS-服务介绍.html', home);
